draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // head
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50 + 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.fill();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30 + 20 * Math.sin(t));
  ctx.lineTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 30 + 20 * Math.cos(t), H/2 + 10 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 10 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 30 + 20 * Math.cos(t), H/2 + 10 + 20 * Math.sin(t));
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(t), H/2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t), H/2 + 90);
  ctx.stroke();

  ctx.restore();
}
